-- ************************************** [CONSUMPTION].[vw_ProductServiceCatalog]
CREATE VIEW [CONSUMPTION].[vw_ProductServiceCatalog] AS
SELECT 
    'Product' AS CatalogItemType,
    p.ProductId AS ItemId,
    p.SKU AS ItemCode,
    p.ProductName AS ItemName,
    p.ProductDescription AS ItemDescription,
    pc.CategoryName,
    sup.SupplierName AS SourceName,
    p.UomCode,
    uom.UomName,
    tc.TaxCategoryName,
    tc.TaxRatePct,
    p.IsActive,
    p.CreatedAt,
    p.UpdatedAt
FROM dbo.Product p
LEFT JOIN dbo.ProductCategory pc ON p.ProductCategoryId = pc.ProductCategoryId
LEFT JOIN dbo.Supplier sup ON p.SupplierId = sup.SupplierId
LEFT JOIN dbo.UnitOfMeasure uom ON p.UomCode = uom.UomCode
LEFT JOIN dbo.TaxCategory tc ON p.TaxCategoryId = tc.TaxCategoryId

UNION ALL

SELECT 
    'Service' AS CatalogItemType,
    s.ServiceId AS ItemId,
    s.ServiceCode AS ItemCode,
    s.ServiceName AS ItemName,
    s.ServiceDescription AS ItemDescription,
    sc.CategoryName,
    NULL AS SourceName,
    s.UomCode,
    uom.UomName,
    tc.TaxCategoryName,
    tc.TaxRatePct,
    s.IsActive,
    s.CreatedAt,
    s.UpdatedAt
FROM dbo.Service s
LEFT JOIN dbo.ServiceCategory sc ON s.ServiceCategoryId = sc.ServiceCategoryId
LEFT JOIN dbo.UnitOfMeasure uom ON s.UomCode = uom.UomCode
LEFT JOIN dbo.TaxCategory tc ON s.TaxCategoryId = tc.TaxCategoryId;
GO
